<?php defined('BASEPATH') or exit('No direct script access allowed');$ds=$discussion_state;$dp=$ds['project'];$wireProject=$native_project_view['canonical_id']??$dp['id'];$dr=$ds['rules'];$discussionHidden=function(string $action,array $extra=[])use($wireProject,$ds,$dp,$esc,$company_project_rules_csrf){foreach(['action'=>$action,'company_project_rules_csrf'=>$company_project_rules_csrf,'request_key'=>bin2hex(random_bytes(32)),'project_id'=>$wireProject,'project_revision'=>$dp['revision'],'discussion_collection_revision'=>$ds['collection_revision']]+$extra as $field=>$value)echo '<input type="hidden" name="'.$esc($field).'" value="'.$esc($value).'">';};$discussionUrl=static fn($id)=>$url('?project='.(int)$dp['id'].'&discussion='.(int)$id); ?>
<section id="project-discussion-rules" style="overflow-wrap:anywhere"><h2>Conversas do projeto no portal</h2><p>Conversas e comentários novos são privados para o autor e a equipe. Publique a conversa e cada comentário separadamente para os contatos autorizados deste cliente. A permissão de iniciar conversas só controla a criação. Edição e exclusão exigem autoria atual, conversa aberta e revisões válidas; comentários com respostas não podem ser excluídos. Suspender uma conversa retira também os resultados privados dos autores; retirar apenas a publicação ampla preserva esses resultados.</p>
<?php if($ds['can_edit']){echo form_open($url(),['id'=>'project-discussion-rules-form']);$discussionHidden('save_discussion_rules',['discussion_rules_revision'=>$dr['revision']]); ?><label><input name="open_discussions" type="checkbox" value="1" <?= $dr['open_discussions']?'checked':''; ?>> Permitir que contatos iniciem novas conversas</label><label><input name="project_discussions" type="checkbox" value="1" <?= $dr['project_discussions']?'checked':''; ?>> Exibir a área de conversas no portal</label><button type="submit">Salvar regras de conversas</button><?= form_close(); ?><?php if($dp['status']==='active'){echo form_open($url('', 'discussion_open'),['id'=>'project-discussion-open']);$discussionHidden('discussion_open'); ?><label for="project-discussion-subject">Assunto interno</label><input style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="project-discussion-subject" name="discussion_subject" maxlength="191" required><label for="project-discussion-body">Texto interno</label><textarea rows="5" style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="project-discussion-body" name="discussion_body" maxlength="8000" required></textarea><button type="submit">Criar conversa interna</button><?= form_close(); ?><?php }} ?>
<ul id="project-discussion-list"><?php foreach($ds['items'] as $item){ ?><li><a href="<?= $esc($discussionUrl($item['id'])); ?>"><?= $esc($item['subject']); ?></a> · <?= $esc($item['author_name']); ?> · <?= (int)$item['active']!==1?'Suspensa':((int)$item['visible']===1?'Publicada':'Privada'); ?></li><?php } ?></ul>
<?php if($ds['thread']){$dt=$ds['thread']; ?><article id="project-discussion-detail"><h3><?= $esc($dt['subject']); ?></h3><p><?= $esc($dt['author_name']); ?> · <?= $esc($dt['created_at']); ?> · <?= $dt['author_type']==='contact'?'Origem: contato':'Origem: equipe'; ?></p><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $esc($dt['body']); ?></p>
<?php if($ds['can_edit']){foreach(['publish'=>['Publicação ampla',(string)$dt['visible'],['0'=>'Privada para autor e equipe','1'=>'Publicada para contatos autorizados']],'active'=>['Disponibilidade',(string)$dt['active'],['0'=>'Suspensa para todos os contatos','1'=>'Ativa']],'status'=>['Novos comentários',$dt['status'],['open'=>'Permitidos em projeto ativo','closed'=>'Conversa encerrada']]] as $kind=>[$label,$current,$options]){echo form_open($url('', 'discussion_thread_state'),['class'=>'project-discussion-state-form','data-kind'=>$kind]);$discussionHidden('discussion_thread_state',['discussion_id'=>$dt['id'],'discussion_revision'=>$dt['revision'],'discussion_state_kind'=>$kind]); ?><label><?= $esc($label); ?> <select name="discussion_state_value"><?php foreach($options as $value=>$text){ ?><option value="<?= $esc($value); ?>" <?= (string)$value===(string)$current?'selected':''; ?>><?= $esc($text); ?></option><?php } ?></select></label><button type="submit">Salvar <?= $esc(mb_strtolower($label)); ?></button><?= form_close(); ?><?php }} ?>
<ol id="project-discussion-posts"><?php foreach($ds['posts'] as $post){ ?><li data-post="<?= (int)$post['id']; ?>"><p><?= $esc($post['author_name']); ?> · <?= $esc($post['created_at']); ?> · <?= $post['author_type']==='contact'?'Contato':'Equipe'; ?></p><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $esc($post['body']); ?></p><?php if($ds['can_edit']&&(int)$dt['active']===1){echo form_open($url(),['class'=>'project-discussion-post-audience']);$discussionHidden('discussion_post_audience',['discussion_id'=>$dt['id'],'discussion_revision'=>$dt['revision'],'discussion_post_id'=>$post['id']]); ?><label>Audiência desta mensagem <select name="discussion_audience"><option value="private" <?= $post['audience']==='private'?'selected':''; ?>>Privada para seu autor e a equipe</option><?php if($dt['author_type']==='contact'){ ?><option value="author" <?= $post['audience']==='author'?'selected':''; ?>>Compartilhar também com o autor da conversa</option><?php }if((int)$dt['visible']===1){ ?><option value="public" <?= $post['audience']==='public'?'selected':''; ?>>Publicar para os contatos autorizados deste cliente</option><?php } ?></select></label><button type="submit">Salvar audiência da mensagem</button><?= form_close(); ?><?php }include __DIR__.'/native_discussion_extras.php'; ?></li><?php } ?></ol>
<?php if($ds['can_edit']&&(int)$dt['active']===1&&$dt['status']==='open'&&$dp['status']==='active'){echo form_open($url('', 'discussion_comment'),['id'=>'project-discussion-comment']);$discussionHidden('discussion_comment',['discussion_id'=>$dt['id'],'discussion_revision'=>$dt['revision']]); ?><label>Responder a comentário<select name="discussion_reply_to"><option value="">Novo comentário sem resposta vinculada</option><?php foreach($ds['posts'] as $replyPost){if((string)$replyPost['active']!=='1')continue; ?><option value="<?= (int)$replyPost['id']; ?>">Comentário #<?= (int)$replyPost['id']; ?></option><?php } ?></select></label><label for="project-discussion-comment-body">Resposta interna da equipe</label><textarea rows="5" style="display:block;width:100%;max-width:100%;box-sizing:border-box" id="project-discussion-comment-body" name="discussion_body" maxlength="8000" required></textarea><p>A resposta começa interna. Compartilhe com o autor da conversa ou publique depois de revisar.</p><button type="submit">Registrar resposta interna</button><?= form_close(); ?><?php } ?></article><?php } ?></section>
